const dividerSizeMap = {
    s: '5rem',
    m: '15rem',
    l: '30rem',
    xl: '35rem',
    auto: '100%',
};
const dividerTypeMap = {
    default: 'solid',
    dot: 'dotted',
    dash: 'dashed',
};
export const mapSizeToCssValue = (size) => {
    return dividerSizeMap[size];
};
export const mapTypeToCssValue = (type) => {
    return dividerTypeMap[type] || 'solid';
};
